osConTipo = CONTENIDOS.map(c => ({    ...c,    respuesta_tipo: c.datos_leccion?.ejercicio?.respuesta_tipo ?? 'abierta'  }));  const preguntasConLabel = TEST_PREGUNTAS.map(p => ({    ...p,    competencia_label: COMPETENCIA_LABELS[p.competencia],    tipo_respuesta: 'escala',    opciones: ESCALA_LIKERT  }));  await TestPregunta.insertMany(preguntasConLabel);  console.log(`${preguntasConLabel.length} preguntas de test creadas`);  await ContenidoDiario.insertMany(contenidosConTipo);  console.log(`${CONTENIDOS.length} contenidos diarios creados`);  await ContenidoEspecial.insertMany(CONTENIDOS_ESPECIALES);  console.log(`${CONTENIDOS_ESPECIALES.length} contenidos especiales creados`);  // Verificaci+¶n de conteos  const [countPreguntas, countEspeciales, countProductos, countCodigos, countPlanes, countUsuarios, countHistorial] = await Promise.all([    TestPregunta.countDocuments(),    ContenidoEspecial.countDocuments(),    Producto.countDocuments(),    Codigo.countDocuments(),    PlanProgreso.countDocuments(),    Usuario.countDocuments(),    HistorialCorreo.countDocuments()  ]);  console.log('\n--- Verificaci+¶n de conteos ---');  console.log(`Usuarios = ${countUsuarios}`);  console.log(`TestPregunta = ${countPreguntas}`);  console.log(`ContenidoEspecial = ${countEspeciales}`);  console.log(`Producto = ${countProductos}`);  console.log(`C+¶digo = ${countCodigos}`);  console.log(`PlanProgreso = ${countPlanes}`);  console.log(`HistorialCorreo = ${countHistorial}`);  console.log('\nSeed completado exitosamente');  await mongoose.disconnect();  process.exit(0);}if (require.main === module) {  seed().catch((err) => {    console.error('Error en seed:', err);    process.exit(1);  });}module.exports = { CONTENIDOS, TEST_PREGUNTAS, CONTENIDOS_ESPECIALES };